function icon(string $name, int $size = 24, string $class = ''): void
{
    // HiMenu / HiX / HiXMark use open line-segment path data (no closed
    // fill area), so they must be stroked like the Outline icons — filling
    // them renders an invisible/zero-area shape (this was the bug behind
    // the invisible popup close button and mobile menu icon).
    $lineStyleIcons = ['HiMenu', 'HiX', 'HiXMark'];
    $isOutline = str_starts_with($name, 'HiOutline') || in_array($name, $lineStyleIcons, true);
    $path = ICON_PATHS[$name] ?? ICON_PATHS['HiOutlineQuestionMarkCircle'];
    $stroke = $isOutline ? 'stroke="currentColor" fill="none" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"' : 'fill="currentColor" stroke="none"';
    printf(
        '<svg class="icon %s" width="%d" height="%d" viewBox="0 0 24 24" %s aria-hidden="true">%s</svg>',
        htmlspecialchars($class),
        $size,
        $size,
        $stroke,
        '<path d="' . $path . '" />'
    );
}

/** Same as icon() but returns a string instead of echoing (useful inside data arrays) */
function icon_html(string $name, int $size = 24, string $class = ''): string
{
    ob_start();
    icon($name, $size, $class);
    return ob_get_clean();
}